package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.util.*;
/** Five different causal computational graphs, trained end-to-end through exact permutation NLL.
 * F03 typed triple messages; F04 dilated TCN; F05 temporal attention; F06 selective SSM;
 * F07 graph GRU. Recurrent gradients use declared one-step truncation. */
public final class NeuralFamilyR26 implements OnlineModelsSU2.Model {
    private static final int W=4,H=8,PARAMETERS=4096;private final String family;private final double[] weights=new double[PARAMETERS],momentum=new double[PARAMETERS],recurrent=new double[40];private final int[][] ring=new int[H][10];private long t;private double lastLoss,gradientNorm;private final AutoDiffR26 tape=new AutoDiffR26(PARAMETERS);private int[] stateNodes;
    public NeuralFamilyR26(String family){if(!Arrays.asList("F03","F04","F05","F06","F07").contains(family))throw new IllegalArgumentException("R26_NEURAL_FAMILY");this.family=family;long seed=Long.parseLong(family.substring(1))*1234567+71;for(int i=0;i<PARAMETERS;i++){seed^=seed<<13;seed^=seed>>>7;seed^=seed<<17;weights[i]=(Math.floorMod(seed,10000)/10000.0-.5)*.2;}}
    private int w(int i){return tape.weight(i,weights);}
    private int zero(){return tape.constant(0);}
    private int sum(int a,int b){return tape.add(a,b);}
    private int mul(int a,int b){return tape.multiply(a,b);}
    private int lag(int lag,int position){if(lag>=Math.min(t,H))return zero();return tape.constant((ring[(int)((t-1-lag)%H)][position]-5.5)/4.5);}
    private int[] embedding(int lag){int[] h=new int[W];if(lag>=Math.min(t,H)){for(int k=0;k<W;k++)h[k]=zero();return h;}for(int k=0;k<W;k++){int z=w(400+k);for(int p=0;p<10;p++){if(lag<Math.min(t,H)){int digit=ring[(int)((t-1-lag)%H)][p]-1;z=sum(z,w((p*10+digit)*W+k));}}h[k]=tape.tanh(z);}return h;}
    private int affine(int base,int[] h,int out){int z=w(base+W*W+out);for(int j=0;j<W;j++)z=sum(z,mul(w(base+out*W+j),h[j]));return z;}
    private int[] tcn(){int[][] x=new int[H][W];for(int i=0;i<H;i++)x[i]=embedding(H-1-i);for(int layer=0;layer<2;layer++){int[][] y=new int[H][W];int dilation=1<<layer,base=420+layer*52;for(int i=0;i<H;i++)for(int k=0;k<W;k++){int z=w(base+48+k);for(int lag=0;lag<3;lag++){int at=i-lag*dilation;if(at<0)continue;for(int j=0;j<W;j++)z=sum(z,mul(w(base+(k*3+lag)*W+j),x[at][j]));}y[i][k]=tape.tanh(sum(z,x[i][k]));}x=y;}return x[H-1];}
    private int[] attention(){int valid=(int)Math.max(1,Math.min(t,H));int[][] x=new int[valid][W],v=new int[valid][W];int[] q=new int[W],energy=new int[valid];for(int i=0;i<valid;i++)x[i]=embedding(i);for(int j=0;j<W;j++)q[j]=affine(540,x[0],j);double maximum=-1e30;for(int i=0;i<valid;i++){int e=zero();for(int k=0;k<W;k++){e=sum(e,mul(q[k],affine(560,x[i],k)));v[i][k]=affine(580,x[i],k);}energy[i]=mul(e,tape.constant(.5));maximum=Math.max(maximum,tape.value(energy[i]));}
        int denominator=zero();int[] e=new int[valid];for(int i=0;i<valid;i++){e[i]=tape.exp(sum(energy[i],tape.constant(-maximum)));denominator=sum(denominator,e[i]);}int[] h=new int[W];for(int k=0;k<W;k++){h[k]=zero();for(int i=0;i<valid;i++)h[k]=sum(h[k],mul(tape.divide(e[i],denominator),v[i][k]));h[k]=tape.tanh(h[k]);}return h;}
    private int[] ssm(){int[] x=embedding(0),h=new int[W];for(int k=0;k<W;k++){int a=tape.sigmoid(affine(610,x,k)),b=tape.tanh(affine(630,x,k));h[k]=sum(mul(a,tape.constant(recurrent[k])),mul(b,x[k]));}stateNodes=h;return h;}
    private int[][] graph(boolean hyper){int[][] x=new int[10][W],h=new int[10][W];for(int p=0;p<10;p++)for(int k=0;k<W;k++){int z=w(405+k);if(t>0){int digit=ring[(int)((t-1)%H)][p]-1;z=sum(z,w((p*10+digit)*W+k));}x[p][k]=tape.tanh(z);}
        stateNodes=new int[40];for(int p=0;p<10;p++){int[] message=new int[W];if(hyper){for(int k=0;k<W;k++){int z=x[p][k];for(int j=0;j<W;j++)z=sum(z,mul(w(660+k*W+j),mul(x[(p+1)%10][j],x[(p+2)%10][j])));h[p][k]=tape.tanh(z);}}
            else{int denominator=zero();int[] edges=new int[10];double max=-1e30;for(int q=0;q<10;q++)max=Math.max(max,weights[700+p*10+q]);for(int q=0;q<10;q++){edges[q]=tape.exp(sum(w(700+p*10+q),tape.constant(-max)));denominator=sum(denominator,edges[q]);}
                for(int k=0;k<W;k++){message[k]=zero();for(int q=0;q<10;q++){int z=x[q][k];for(int j=0;j<W;j++)z=sum(z,mul(w(800+k*W+j),tape.constant(recurrent[q*W+j])));message[k]=sum(message[k],mul(tape.divide(edges[q],denominator),tape.tanh(z)));}}
                int[] reset=new int[W],update=new int[W];for(int k=0;k<W;k++){reset[k]=tape.sigmoid(sum(affine(830,message,k),mul(w(900+k),tape.constant(recurrent[p*W+k]))));update[k]=tape.sigmoid(sum(affine(850,message,k),mul(w(904+k),tape.constant(recurrent[p*W+k]))));}
                for(int k=0;k<W;k++){int z=affine(870,message,k);for(int j=0;j<W;j++)z=sum(z,mul(w(920+k*W+j),mul(reset[j],tape.constant(recurrent[p*W+j]))));h[p][k]=sum(mul(update[k],tape.constant(recurrent[p*W+k])),mul(sum(tape.constant(1),mul(tape.constant(-1),update[k])),tape.tanh(z)));}}
            for(int k=0;k<W;k++)stateNodes[p*W+k]=h[p][k];}return h;
    }
    private int[] forward(){tape.reset();stateNodes=null;int[] h=null;int[][] graph=null;switch(family){case "F03":graph=graph(true);break;case "F04":h=tcn();break;case "F05":h=attention();break;case "F06":h=ssm();break;case "F07":graph=graph(false);break;default:throw new AssertionError();}int[] output=new int[100];for(int p=0;p<10;p++)for(int n=0;n<10;n++){int j=p*10+n,z=w(1500+j);for(int k=0;k<W;k++)z=sum(z,mul(w(1000+j*W+k),graph==null?h[k]:graph[p][k]));output[j]=z;}return output;}
    private double[][] table(int[] output){double[][] s=new double[10][10];for(int i=0;i<100;i++)s[i/10][i%10]=tape.value(output[i]);return s;}
    double objective(int[] draw){int[] out=forward(),target=new int[10];for(int p=0;p<10;p++)target[p]=draw[p]-1;double[][] s=table(out);return ExactPermutationR26.nll(s,target,ExactPermutationR26.infer(s,null));}
    public int stateWidth(){return 3;}
    public void predict(float[][] p,float[] st){ExactPermutationR26.Result r=ExactPermutationR26.infer(table(forward()),null);for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=(float)r.marginal[i][j];st[0]=(float)Math.log1p(t);st[1]=(float)lastLoss;st[2]=(float)gradientNorm;}
    public void update(int[] draw){OnlineModelsSU2.requireDraw(draw);int[] out=forward();double[][] s=table(out);ExactPermutationR26.Result r=ExactPermutationR26.infer(s,null);double[] seed=new double[100];int[] target=new int[10];for(int p=0;p<10;p++){target[p]=draw[p]-1;for(int n=0;n<10;n++)seed[p*10+n]=r.marginal[p][n]-(draw[p]==n+1?1:0);}lastLoss=ExactPermutationR26.nll(s,target,r);double[] gradient=tape.backward(out,seed);gradientNorm=0;for(double x:gradient)gradientNorm+=x*x;gradientNorm=Math.sqrt(gradientNorm);double scale=gradientNorm>5?5/gradientNorm:1;
        if(stateNodes!=null)for(int i=0;i<stateNodes.length;i++)recurrent[i]=tape.value(stateNodes[i]);for(int i=0;i<PARAMETERS;i++){momentum[i]=.9*momentum[i]+.1*gradient[i]*scale;weights[i]=Math.max(-6,Math.min(6,weights[i]-.03*momentum[i]));}ring[(int)(t%H)]=draw.clone();t++;
    }
    public void write(DataOutput o)throws IOException{o.writeInt(0x26220001);o.writeUTF(family);o.writeLong(t);o.writeDouble(lastLoss);o.writeDouble(gradientNorm);for(int[] row:ring)for(int n:row)o.writeInt(n);for(double[] a:new double[][]{weights,momentum,recurrent})for(double x:a)o.writeDouble(x);}
    public void read(DataInput in)throws IOException{if(in.readInt()!=0x26220001||!family.equals(in.readUTF()))throw new IOException("R26_NEURAL_ABI");t=in.readLong();lastLoss=in.readDouble();gradientNorm=in.readDouble();if(t<0||!Double.isFinite(lastLoss)||!Double.isFinite(gradientNorm))throw new IOException("R26_NEURAL_STATE");for(int[] row:ring)for(int j=0;j<10;j++){row[j]=in.readInt();if(row[j]<0||row[j]>10)throw new IOException("R26_NEURAL_HISTORY");}for(double[] a:new double[][]{weights,momentum,recurrent})for(int j=0;j<a.length;j++){a[j]=in.readDouble();if(!Double.isFinite(a[j])||Math.abs(a[j])>1e8)throw new IOException("R26_NEURAL_PARAMETER");}}
}
